import React from 'react';
import { Progress } from '../ui/progress';
import { Star } from 'lucide-react';
import CriteriaRating from './CriteriaRating';

const RatingSummary = ({ summary, reviews }) => {
    if ((!summary || summary.total_reviews === 0) && (!reviews || reviews.length === 0)) {
        return (
            <div className="flex items-center justify-center p-4 bg-slate-50 rounded-xl border border-slate-100">
                <p className="text-slate-500 text-sm">No reviews yet. Be the first to review!</p>
            </div>
        );
    }

    if (!summary && reviews && reviews.length > 0) {
        // calculate average manually
        const total_reviews = reviews.length;
        const sum = reviews.reduce((acc, curr) => acc + (Number(curr.rating) || 0), 0);
        const average_rating = (sum / total_reviews).toFixed(1);
        return (
            <div className="flex items-center justify-center space-2 mb-4 pb-1 border-b border-slate-200 gap-2">
                <div className="flex items-center gap-2">
                    <Star className="w-6 h-6 fill-amber-400 text-amber-400" />
                    <span className="text-3xl font-bold tracking-tighter text-slate-900">
                        {average_rating}
                    </span>
                </div>
                <p className="text-slate-500 text-sm">Based on {total_reviews} review{total_reviews !== 1 ? 's' : ''}</p>
            </div>
        );
    }

    const { average_rating, total_reviews, rating_distribution, criteria_averages } = summary;

    return (
        <div className="grid grid-cols-1 md:grid-cols-12 gap-4 mb-4 pb-4 border-b border-slate-200">
            {/* Overall Score Area */}
            <div className="md:col-span-4 flex flex-col justify-center items-center md:items-start space-y-1">
                <div className="flex items-center gap-2">
                    <Star className="w-6 h-6 fill-amber-400 text-amber-400" />
                    <span className="text-3xl font-bold tracking-tighter text-slate-900">
                        {Number(average_rating || 0).toFixed(1)}
                    </span>
                </div>
                <p className="text-slate-500 text-sm">Based on {total_reviews} review{total_reviews !== 1 ? 's' : ''}</p>
            </div>

            {/* Distribution Bars */}
            <div className="md:col-span-4 flex flex-col justify-center space-y-2">
                {[5, 4, 3, 2, 1].map((star) => {
                    const count = rating_distribution?.[star.toString()] || 0;
                    const percentage = total_reviews > 0 ? (count / total_reviews) * 100 : 0;

                    return (
                        <div key={star} className="flex items-center gap-3 text-sm">
                            <span className="font-medium text-slate-700 w-3">{star}</span>
                            <Progress value={percentage} className="h-2.5 flex-1" />
                            <span className="text-slate-500 w-8 text-right text-xs">{count}</span>
                        </div>
                    );
                })}
            </div>

            {/* Criteria Averages */}
            <div className="md:col-span-4 flex flex-col justify-center border-l pl-8 border-slate-200 hidden md:flex">
                <div className="space-y-1">
                    {Object.entries(criteria_averages || {}).map(([key, value]) => (
                        <CriteriaRating
                            key={key}
                            label={key.charAt(0).toUpperCase() + key.slice(1)}
                            value={Number(value)}
                            readonly={true}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default RatingSummary;