import React from 'react';
import { Star } from 'lucide-react';

const CriteriaRating = ({ label, value, onChange, readonly = false }) => {
    // Array to help render 5 stars
    const stars = [1, 2, 3, 4, 5];

    return (
        <div className="flex items-center justify-between py-1">
            <span className="text-sm font-medium text-slate-700 w-1/3">{label}</span>
            <div className="flex items-center space-x-1 flex-1 justify-start ml-4">
                {stars.map((star) => (
                    <button
                        key={star}
                        type="button"
                        disabled={readonly}
                        onClick={() => !readonly && onChange && onChange(star)}
                        className={`focus:outline-none transition-colors ${
                            readonly ? 'cursor-default' : 'cursor-pointer hover:scale-110'
                        }`}
                        aria-label={`Rate ${star} stars out of 5 for ${label}`}
                    >
                        <Star
                            className={`w-5 h-5 ${
                                star <= value
                                    ? 'fill-amber-400 text-amber-400'
                                    : 'fill-transparent text-slate-300'
                            }`}
                        />
                    </button>
                ))}
                {readonly && value > 0 && (
                    <span className="ml-2 text-sm text-slate-500 w-6 text-right">
                        {value.toFixed(1)}
                    </span>
                )}
            </div>
        </div>
    );
};

export default CriteriaRating;
