import React, { useState, useEffect, useCallback } from 'react';
import { reviewService } from '../../api/listingService';
import RatingSummary from './RatingSummary';
import ReviewCard from './ReviewCard';
import { Button } from '../ui/button';
import { toast } from 'sonner';

const ReviewList = ({ itemId, currentUser, onStatsChange }) => {
    const [reviews, setReviews] = useState([]);
    const [summary, setSummary] = useState(null);
    const [loading, setLoading] = useState(true);
    const [loadingMore, setLoadingMore] = useState(false);
    const [lastKey, setLastKey] = useState(null);
    const [hasMore, setHasMore] = useState(false);
    const [error, setError] = useState(null);

    const fetchReviews = useCallback(async (isInitial = true) => {
        try {
            if (isInitial) setLoading(true);
            else setLoadingMore(true);

            const response = await reviewService.getReviewsForItem(itemId, 5, isInitial ? null : lastKey);
            
            if (isInitial) {
                setReviews(response.reviews || []);
                setSummary(response.summary || null);
                if (onStatsChange) {
                    let total = 0;
                    let average = 0;
                    
                    if (response.summary && response.summary.total_reviews > 0) {
                        total = Number(response.summary.total_reviews);
                        average = Number(response.summary.average_rating);
                    } else if (response.reviews && response.reviews.length > 0) {
                        // Fallback manual calculation if API doesn't return summary object
                        total = response.reviews.length;
                        const sum = response.reviews.reduce((acc, curr) => acc + (Number(curr.rating) || 0), 0);
                        average = sum / total;
                    }

                    onStatsChange({ average, total });
                }
            } else {
                setReviews(prev => [...prev, ...(response.reviews || [])]);
            }

            setHasMore(response.pagination?.hasMore || false);
            
            // Handle lastEvaluatedKey decoding
            if (response.pagination?.lastEvaluatedKey) {
                setLastKey(JSON.parse(decodeURIComponent(response.pagination.lastEvaluatedKey)));
            } else {
                setLastKey(null);
            }
            
            setError(null);
        } catch (err) {
            console.error("Failed to fetch reviews:", err);
            setError("Failed to load reviews. Please try again later.");
            if (isInitial) setReviews([]);
        } finally {
            setLoading(false);
            setLoadingMore(false);
        }
    }, [itemId, lastKey, onStatsChange]);

    // Initial fetch
    useEffect(() => {
        if (itemId) {
            fetchReviews(true);
        }
    }, [itemId, fetchReviews]);

    const handleDeleteReview = async (reviewId) => {
        if (!window.confirm("Are you sure you want to delete this review?")) return;
        
        try {
            await reviewService.deleteReview(reviewId);
            toast.success("Review deleted successfully");
            
            // Remove from local state
            setReviews(prev => prev.filter(r => r.review_id !== reviewId));
            
            // Optionally, refresh summary (though it updates async on backend)
            // fetchReviews(true); 
        } catch (err) {
            console.error(err);
            toast.error(err.message || "Failed to delete review");
        }
    };

    const handleVoteHelpful = async (reviewId, isHelpful) => {
        try {
            await reviewService.markReviewHelpful(reviewId, isHelpful);
            toast.success("Thank you for your feedback!");
            
            // Optimistically update the UI
            setReviews(prev => prev.map(r => {
                if (r.review_id === reviewId) {
                    return {
                        ...r,
                        [isHelpful ? 'helpful_count' : 'not_helpful_count']: r[isHelpful ? 'helpful_count' : 'not_helpful_count'] + 1
                    };
                }
                return r;
            }));
        } catch (err) {
            console.error(err);
            toast.error("Failed to record vote");
        }
    };

    // If there's an error on initial load
    if (error && reviews.length === 0) {
        return (
            <div className="py-8 text-center bg-red-50 rounded-lg border border-red-100">
                <p className="text-red-600 mb-4">{error}</p>
                <Button variant="outline" onClick={() => fetchReviews(true)}>Try Again</Button>
            </div>
        );
    }

    return (
        <div className="pt-2">
            <h3 className="text-xl font-bold tracking-tight text-slate-900">Reviews</h3>
            
            {/* Loading Skeleton for initial load */}
            {loading ? (
                <div className="space-y-4">
                    <div className="h-24 bg-slate-100 animate-pulse rounded-xl"></div>
                    <div className="space-y-3">
                        {[1, 2].map(i => (
                            <div key={i} className="h-20 bg-slate-100 animate-pulse rounded-xl"></div>
                        ))}
                    </div>
                </div>
            ) : (
                <>
                    {/* Rating Summary */}
                    <RatingSummary summary={summary} reviews={reviews} />

                    {/* Review Cards */}
                    <div className="space-y-0">
                        {reviews.length > 0 ? (
                            reviews.map((review) => (
                                <ReviewCard 
                                    key={review.review_id}
                                    review={review}
                                    currentUser={currentUser}
                                    onEdit={() => {
                                        toast.info("To edit, go to your Bookings page.");
                                        // Complex state logic to handle edit modal from here would be messy.
                                        // Best handled from the StudentBookings page where the form lives.
                                    }}
                                    onDelete={handleDeleteReview}
                                    onVote={handleVoteHelpful}
                                />
                            ))
                        ) : (
                            // Handled largely by RatingSummary, but just in case
                            null 
                        )}
                    </div>

                    {/* Load More Button */}
                    {hasMore && (
                        <div className="mt-8 flex justify-center">
                            <Button 
                                variant="outline" 
                                onClick={() => fetchReviews(false)}
                                disabled={loadingMore}
                                className="w-full md:w-auto min-w-[200px]"
                            >
                                {loadingMore ? 'Loading...' : 'Show More Reviews'}
                            </Button>
                        </div>
                    )}
                </>
            )}
        </div>
    );
};

export default ReviewList;