import React, { useState } from 'react';
import { Card, CardContent } from '../ui/card';
import { Avatar, AvatarFallback } from '../ui/avatar';
import { Button } from '../ui/button';
import { Star, ThumbsUp, ThumbsDown, MoreVertical, Edit2, Trash2 } from 'lucide-react';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '../ui/dropdown-menu';

const ReviewCard = ({ review, currentUser, onEdit, onDelete, onVote }) => {
    const [voted, setVoted] = useState(null); // 'helpful' or 'not_helpful'
    
    // Safety checks
    if (!review) return null;

    const { 
        review_id, user_id, rating = 5, text, comment, created_at, 
        edited, helpful_count = 0, not_helpful_count = 0, author_name 
    } = review;

    const reviewContent = text || comment || "Great accommodation!";
    const isAuthor = currentUser?.userId === user_id || currentUser?.id === user_id;
    const isAdmin = currentUser?.role === 'admin' || currentUser?.groups?.includes('admin');
    
    const canEdit = isAuthor;
    const canDelete = isAuthor || isAdmin;

    const handleVote = (type) => {
        if (!currentUser) return;
        if (voted) return;
        setVoted(type);
        if (onVote) onVote(review_id, type === 'helpful');
    };

    // Render stars helper
    const renderStars = () => {
        const numRating = Number(rating) || 5;
        return (
            <div className="flex items-center space-x-0.5">
                {[1, 2, 3, 4, 5].map((star) => (
                    <Star
                        key={star}
                        className={`w-4 h-4 ${
                            star <= numRating
                                ? 'fill-amber-400 text-amber-400'
                                : 'fill-transparent text-slate-200'
                        }`}
                    />
                ))}
            </div>
        );
    };

    // Format date string safely
    const dateString = created_at ? new Date(created_at).toLocaleDateString() : 'Recently';

    return (
        <Card className="mb-4 overflow-hidden border-slate-200 shadow-sm transition-all hover:shadow-md">
            <CardContent className="p-5">
                <div className="flex justify-between items-start mb-3">
                    {/* User Info & Rating */}
                    <div className="flex items-center gap-3">
                        <Avatar className="h-10 w-10 border border-slate-100">
                            <AvatarFallback className="bg-primary/10 text-primary font-semibold">
                                {author_name ? author_name.substring(0, 2).toUpperCase() : (user_id ? user_id.substring(0, 2).toUpperCase() : 'ST')}
                            </AvatarFallback>
                        </Avatar>
                        <div>
                            <div className="flex items-center gap-2">
                                <span className="font-semibold text-slate-900 text-sm">{author_name || 'Verified Student'}</span>
                                <span className="text-xs text-slate-500">• {dateString} {edited && '(edited)'}</span>
                            </div>
                            <div className="mt-0.5">{renderStars()}</div>
                        </div>
                    </div>

                    {/* Actions Menu (Edit/Delete) */}
                    {(canEdit || canDelete) && (
                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-8 w-8 text-slate-500 -mr-2">
                                    <MoreVertical className="h-4 w-4" />
                                </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                                {canEdit && onEdit && (
                                    <DropdownMenuItem onClick={() => onEdit(review)}>
                                        <Edit2 className="h-4 w-4 mr-2" /> Edit Review
                                    </DropdownMenuItem>
                                )}
                                {canDelete && onDelete && (
                                    <DropdownMenuItem onClick={() => onDelete(review_id)} className="text-red-600 focus:text-red-600">
                                        <Trash2 className="h-4 w-4 mr-2" /> Delete Review
                                    </DropdownMenuItem>
                                )}
                            </DropdownMenuContent>
                        </DropdownMenu>
                    )}
                </div>

                {/* Review Text */}
                {reviewContent && (
                    <p className="text-slate-700 text-sm leading-relaxed mb-4 whitespace-pre-wrap">
                        {reviewContent}
                    </p>
                )}

                {/* Helpful Actions */}
                <div className="flex items-center gap-3 mt-2">
                    <span className="text-xs text-slate-500 font-medium">Was this helpful?</span>
                    <div className="flex items-center gap-2">
                        <Button 
                            variant="outline" 
                            size="sm" 
                            className={`h-7 px-2.5 text-xs gap-1.5 ${voted === 'helpful' ? 'bg-green-50 text-green-700 border-green-200' : 'text-slate-600'}`}
                            onClick={() => handleVote('helpful')}
                            disabled={voted !== null}
                        >
                            <ThumbsUp className="h-3 w-3" />
                            {(Number(helpful_count) || 0) + (voted === 'helpful' ? 1 : 0)}
                        </Button>
                        <Button 
                            variant="outline" 
                            size="sm" 
                            className={`h-7 px-2.5 text-xs gap-1.5 ${voted === 'not_helpful' ? 'bg-red-50 text-red-700 border-red-200' : 'text-slate-600'}`}
                            onClick={() => handleVote('not_helpful')}
                            disabled={voted !== null}
                        >
                            <ThumbsDown className="h-3 w-3" />
                            {(Number(not_helpful_count) || 0) + (voted === 'not_helpful' ? 1 : 0)}
                        </Button>
                    </div>
                </div>
            </CardContent>
        </Card>
    );
};

export default ReviewCard;